class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        map<char, int> cnt;
        for (char t : tasks) cnt[t]++;
        int most = 0, ties = 0;
        for (auto& [t, c] : cnt) most = max(most, c);
        for (auto& [t, c] : cnt) ties += c == most;
        int frame = (most - 1) * (n + 1) + ties;
        return max(frame, (int)tasks.size());
    }
};
